// Display names mirror hermes_cli/models.py CANONICAL_PROVIDERS/_PROVIDER_LABELS
// (what the model picker shows). Visual style matches the main model menu:
// neutral theme tokens, no brand colors.
const PROVIDER_META = {
	anthropic: { name: "Anthropic", mono: "A" },
	"openai-codex": { name: "OpenAI Codex", mono: "O" },
	nous: { name: "Nous Portal", mono: "N" },
	openrouter: { name: "OpenRouter", mono: "OR" },
	deepseek: { name: "DeepSeek", mono: "DS" },
	experientiallabs: { name: "Experiential Labs", mono: "XL" },
	gemini: { name: "Google Gemini", mono: "G" },
	kimi: { name: "Kimi / Moonshot", mono: "K" },
	grok: { name: "xAI Grok", mono: "X" },
	"opencode-go": { name: "OpenCode Go", mono: "OC" },
	copilot: { name: "Copilot", mono: "CP" },
	zai: { name: "Z.ai", mono: "Z" },
	commandcode: { name: "CommandCode", mono: "CC" },
	cursor: { name: "Cursor", mono: "CU" },
	antigravity: { name: "Antigravity", mono: "AG" },
	minimax: { name: "MiniMax", mono: "MM" },
	ollama: { name: "Ollama", mono: "OL" },
};

function baseProviderId(pid) {
	// Extra accounts are cached as <provider>:<account_id>; the icon and
	// display name come from the base provider, while the account label
	// distinguishes the row.
	const text = String(pid || "");
	const colon = text.indexOf(":");
	return colon > 0 ? text.slice(0, colon) : text;
}

function providerMeta(pid) {
	const base = baseProviderId(pid);
	return (
		PROVIDER_META[base] || {
			name: base,
			mono: String(base || "?")
				.slice(0, 2)
				.toUpperCase(),
		}
	);
}

// A row's own account label is preferred over the plain provider name so a
// second Claude login reads "Anthropic · Work" instead of a duplicate
// "Anthropic".
function providerDisplayName(pid, provider) {
	const meta = providerMeta(pid);
	let account =
		provider && typeof provider.account_label === "string"
			? provider.account_label.trim()
			: "";
	if (!account) {
		// Fall back to the pid suffix ("anthropic:work") when the provider
		// object is missing, so an account row is never shown as a bare
		// duplicate of its base provider.
		const text = String(pid || "");
		const colon = text.indexOf(":");
		account = colon > 0 ? text.slice(colon + 1).trim() : "";
	}
	return account ? `${meta.name} · ${account}` : meta.name;
}

function ProviderBadge({ pid }) {
	const meta = providerMeta(pid);
	const svg = PROVIDER_SVGS[baseProviderId(pid)];
	if (svg) {
		// dangerouslySetInnerHTML is safe here: the path data is a build-time
		// constant inlined from @lobehub/icons, never user input.
		return jsx("span", {
			className:
				"inline-flex h-5 w-5 shrink-0 items-center justify-center text-(--ui-text-secondary)",
			children: jsx("svg", {
				viewBox: svg.viewBox,
				width: "1em",
				height: "1em",
				fill: "currentColor",
				className: "text-[0.875rem]",
				dangerouslySetInnerHTML: { __html: svg.body },
			}),
		});
	}
	return jsx("span", {
		className:
			"inline-flex h-5 w-5 shrink-0 items-center justify-center rounded bg-(--ui-control-hover-background) text-[0.625rem] font-semibold uppercase tracking-wide text-(--ui-text-secondary)",
		children: meta.mono,
	});
}

// ---- severity helpers -----------------------------------------------------

function toneForRemaining(pct) {
	if (pct == null) return "muted";
	if (pct <= 15) return "bad";
	if (pct <= 40) return "warn";
	return "good";
}

// Theme tokens that actually exist in the Desktop app. --ui-danger/--ui-warning
// do NOT exist as theme variables (the core app only ever uses them with an
// inline fallback), so use the real ones: --ui-red / --ui-yellow / --ui-accent.
function toneColor(tone) {
	if (tone === "bad") return "var(--ui-red)";
	if (tone === "warn") return "var(--ui-yellow)";
	if (tone === "good") return "var(--ui-accent)";
	return "var(--ui-stroke-tertiary)";
}

function remainingPct(w) {
	// Cache stores used_percent; widget shows remaining = 100 - used.
	const used = w && w.used_percent;
	if (used == null) return null;
	const n = Number(used);
	if (!Number.isFinite(n)) return null;
	return Math.max(0, Math.min(100, Math.round(100 - n)));
}

// A provider record comes from a JSON cache file that a truncated write, a
// hand edit, or an older/newer backend can leave in any shape. `x || []` is
// null-safe but not type-safe: `{}` and `"text"` are both truthy and reach
// .map/.filter/spread. These normalise, matching accountFacts' Array.isArray.
function asList(value) {
	return Array.isArray(value) ? value : [];
}

function asWindowList(value) {
	return asList(value).filter(
		(window) => window && typeof window === "object" && !Array.isArray(window),
	);
}

function asProvider(value) {
	return value && typeof value === "object" && !Array.isArray(value) ? value : null;
}

function worstWindow(provider) {
	let worst = null;
	for (const w of asWindowList(provider && provider.windows)) {
		const r = remainingPct(w);
		if (r == null) continue;
		if (worst == null || r < worst) worst = r;
	}
	return worst;
}

// Monetary account facts never become percentage windows or key caps.
function accountFacts(provider) {
	if (!provider || provider.unavailable_reason) return { balances: [], available: null };
	const rows = provider.account_balances;
	const available = typeof provider.api_calls_available === "boolean" ? provider.api_calls_available : null;
	const balances = (Array.isArray(rows) ? rows : []).filter((b) =>
		b && /^[A-Z]{3}$/.test(b.currency) &&
		(typeof b.total_balance === "number" || (typeof b.total_balance === "string" && /^-?\d+(?:\.\d+)?$/.test(b.total_balance))) &&
		Number.isFinite(Number(b.total_balance)),
	);
	return { balances, available };
}

// Fraction digits the endpoint actually reported, so a sub-cent total is not
// rendered as a rounded zero (a nonzero balance reading "$0.00" looks empty).
function balanceFractionDigits(raw) {
	const dot = raw.indexOf(".");
	if (dot === -1) return 2;
	return Math.min(Math.max(2, raw.length - dot - 1), 20);
}

function balanceText(balance, locale) {
	const raw = String(balance.total_balance).trim();
	// Prefer the endpoint's own decimal string: Number() silently rounds past
	// 2^53 (9007199254740993.00 came back as ...992) and to 17 significant
	// digits, which Intl's maximumFractionDigits cannot recover.
	if (/^-?\d+(?:\.\d+)?$/.test(raw)) {
		const currency = balance.currency;
		const digits = Math.max(2, balanceFractionDigits(raw));
		const [whole, fraction = ""] = raw.replace(/^-/, "").split(".");
		const shownFraction = (fraction + "0".repeat(digits)).slice(0, digits);
		let formatted = null;
		try {
			const formatter = new Intl.NumberFormat(locale, {
				style: "currency", currency,
				minimumFractionDigits: 2,
				maximumFractionDigits: 2,
			});
			// Ask Intl only for the locale's formatting pattern. The sample's
			// numeric value is never used as the reported balance, so large
			// endpoint strings retain every digit without Number() rounding.
			const sample = raw.startsWith("-") ? -1234567890123.45 : 1234567890123.45;
			const parts = formatter.formatToParts(sample);
			const firstNumber = parts.findIndex((p) => p.type === "integer");
			let lastNumber = -1;
			for (let i = firstNumber; i < parts.length; i += 1) {
				if (["integer", "group", "decimal", "fraction"].includes(parts[i].type)) {
					lastNumber = i;
				}
			}
			if (firstNumber >= 0 && lastNumber >= firstNumber) {
				const integerParts = parts
					.slice(firstNumber, lastNumber + 1)
					.filter((p) => p.type === "integer");
				const group = parts.find((p) => p.type === "group")?.value || "";
				const primarySize = integerParts[integerParts.length - 1]?.value.length || 3;
				const secondarySize = integerParts.length > 1
					? integerParts[integerParts.length - 2].value.length
					: primarySize;
				let grouped = whole;
				if (group && primarySize > 0 && secondarySize > 0 && whole.length > primarySize) {
					let rest = whole;
					const groups = [rest.slice(-primarySize)];
					rest = rest.slice(0, -primarySize);
					while (rest.length > secondarySize) {
						groups.unshift(rest.slice(-secondarySize));
						rest = rest.slice(0, -secondarySize);
					}
					if (rest) groups.unshift(rest);
					grouped = groups.join(group);
				}
				const decimal = parts.find((p) => p.type === "decimal")?.value || ".";
				const number = `${grouped}${decimal}${shownFraction}`;
				formatted = parts.slice(0, firstNumber).map((p) => p.value).join("") +
					number + parts.slice(lastNumber + 1).map((p) => p.value).join("");
			}
		} catch {
			// Unknown locale/currency: keep a readable fallback rather than
			// rendering nothing.
		}
		if (formatted == null) {
			const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
			const sign = raw.startsWith("-") ? "-" : "";
			formatted = `$${sign}${grouped}.${shownFraction}`;
		}
		return `${formatted} ${currency}`;
	}
	const n = Number(raw);
	const format = (value) => new Intl.NumberFormat(undefined, {
		style: "currency", currency: balance.currency,
		minimumFractionDigits: 2, maximumFractionDigits: balanceFractionDigits(raw),
	}).format(value);
	const money = format(n);
	// Past Intl's precision ceiling the reported value is shown verbatim rather
	// than a rounded zero.
	if (n !== 0 && money === format(0)) return `${raw} ${balance.currency}`;
	return `${money} ${balance.currency}`;
}

function providerTone(provider) {
	if (!provider) return "muted";
	if (provider.unavailable_reason) return "muted";
	const r = worstWindow(provider);
	if (r != null) return toneForRemaining(r);
	const { available } = accountFacts(provider);
	return available === true ? "good" : available === false ? "bad" : "muted";
}

function checkedDateTime(iso) {
	if (!iso) return "";
	const dt = new Date(iso);
	if (!Number.isFinite(dt.getTime())) return "";
	return new Intl.DateTimeFormat(undefined, {
		year: "numeric", month: "short", day: "2-digit",
		hour: "2-digit", minute: "2-digit", second: "2-digit", timeZoneName: "short",
	}).format(dt);
}

// Short absolute reset: today/tomorrow/time, else "Aug 11, 2:30 PM".
function absoluteReset(resetIso) {
	if (!resetIso) return "";
	try {
		const dt = new Date(resetIso);
		if (isNaN(dt.getTime())) return "";
		const now = new Date();
		const sameDay = dt.toDateString() === now.toDateString();
		const tomorrow = new Date(now);
		tomorrow.setDate(now.getDate() + 1);
		const isTomorrow = dt.toDateString() === tomorrow.toDateString();
		const time = dt.toLocaleTimeString([], {
			hour: "2-digit",
			minute: "2-digit",
		});
		if (sameDay) return `today ${time}`;
		if (isTomorrow) return `tomorrow ${time}`;
		return fmtDayTime.format(dt);
	} catch {
		return "";
	}
}

// Short relative countdown, e.g. "resets in 3h 12m". `nowMs` lets the UI tick.
function relativeCountdown(resetIso, nowMs = Date.now()) {
	if (!resetIso) return "";
	try {
		const dt = new Date(resetIso);
		const target = dt.getTime();
		if (isNaN(target)) return "";
		const diff = target - nowMs;
		if (diff <= 0) return "resetting…";
		const totalMin = Math.floor(diff / 60_000);
		const days = Math.floor(totalMin / 1440);
		const hours = Math.floor((totalMin % 1440) / 60);
		const mins = totalMin % 60;
		if (days > 0) return `${days}d ${hours}h`;
		if (hours > 0) return `${hours}h ${mins}m`;
		if (mins > 0) return `${mins}m`;
		return "<1m";
	} catch {
		return "";
	}
}

// Format a reset timestamp per the persisted format setting.
function formatReset(resetIso, format) {
	if (!resetIso) return "";
	if (format === "absolute") return absoluteReset(resetIso);
	const relative = relativeCountdown(resetIso);
	const absolute = absoluteReset(resetIso);
	return absolute ? `${relative} (${absolute})` : relative;
}

function isConfigured(provider) {
	return provider && !provider.unavailable_reason;
}

// Re-render on an interval so relative countdowns tick live.
function useNow(intervalMs = 30_000) {
	const [now, setNow] = useState(() => Date.now());
	useEffect(() => {
		const id = setInterval(() => setNow(Date.now()), intervalMs);
		return () => clearInterval(id);
	}, [intervalMs]);
	return now;
}

/** Compact age label for the "data is N old" footer line. */
function formatAgeSeconds(seconds) {
	if (!Number.isFinite(seconds)) return "";
	if (seconds < 60) return `${Math.round(seconds)}s`;
	if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
	return `${Math.floor(seconds / 3600)}h`;
}

// ---- update self-check (like Hermes's own) ---------------------------------

const REPO_API_LATEST =
	"https://api.github.com/repos/rarf/hermes-quota-plugin/commits/master";

// Compare the installed commit stamp against GitHub master. One cheap
// request per hour, cached in storage; never blocks rendering. The cache
// entry is bound to the stamp it was taken with (`seen`) — so installing
// a new version invalidates it immediately instead of serving a stale
// "update available" verdict for the rest of the hour.
function useUpdateCheck(installedSha) {
	const [update, setUpdate] = useState(null);
	useEffect(() => {
		let alive = true;
		const CHECK_KEY = "updateCheck";
		const ONE_HOUR = 60 * 60 * 1000;
		const run = async () => {
			// The stamp rides on the status payload — no second CLI spawn on
			// mount, which is what made a reload (or a gateway switch, where
			// every plugin re-mounts) feel sluggish.
			if (!installedSha || installedSha === "unknown") return;
			// Throttle: at most one GitHub call per hour. The cached verdict
			// is only valid for the installed stamp it was taken with — a
			// fresh install must re-check immediately.
			try {
				const prev = CTX.storage.get(CHECK_KEY);
				if (prev) {
					const p = JSON.parse(prev);
					if (
						p.at &&
						Date.now() - p.at < ONE_HOUR &&
						p.latest &&
						p.seen === installedSha
					) {
						if (p.latest !== installedSha) {
							setUpdate({ latest: p.latest });
						}
						return;
					}
				}
			} catch {
				/* noop */
			}
			try {
				const res = await fetch(REPO_API_LATEST, {
					headers: { Accept: "application/vnd.github+json" },
				});
				if (!res.ok) return;
				const j = await res.json();
				const latest = j && j.sha;
				if (!latest) return;
				try {
					CTX.storage.set(
						CHECK_KEY,
						JSON.stringify({
							at: Date.now(),
							latest,
							seen: installedSha,
						}),
					);
				} catch {
					/* noop */
				}
				if (alive && latest !== installedSha) {
					setUpdate({ latest });
				}
			} catch {
				/* offline / rate-limited — stay quiet */
			}
		};
		run();
		return () => {
			alive = false;
		};
	}, [installedSha]);
	return update;
}

function UpdateBanner({ update }) {
	if (!update) return null;
	return jsxs("button", {
		type: "button",
		className: cn(
			"flex w-full items-center justify-between gap-2 rounded px-3 py-2 text-left text-[0.6875rem]",
			"bg-(--chrome-action) text-(--ui-text-secondary) hover:bg-(--chrome-action-hover) transition-colors",
		),
		onClick: () =>
			host.openExternal?.("https://github.com/rarf/hermes-quota-plugin"),
		children: [
			jsx("span", {
				className: "font-medium",
				children: "⬆ Update available — run ./install.sh to get it",
			}),
			jsx("span", { className: "text-(--ui-text-tertiary)", children: "↗" }),
		],
	});
}

// ---- data hook (cli.exec instead of REST) ----------------------------------
//
// Two-phase by design. The POLL reads the backend cache (`--cached`, never the
// network), so the configured interval IS the cadence; the refresh is fired
// out-of-band. Blocking the poll on a provider fetch is what stretched a 60s
// setting to 100-200s (providers ran one after another, and one flaky endpoint
// held the whole sweep). The last payload is kept in storage, so a plugin
// reload or a gateway switch paints from it immediately instead of waiting for
// a CLI spawn.

const QUOTA_QUERY_KEY = ["quota", "widget"];
const SNAPSHOT_KEY = "lastPayload";
const CLI_TIMEOUT_MS = 15_000;
const _refreshInFlight = new Set();

function normalizeQuotaScope(owner) {
	const connectionId = String(owner?.connectionId || "").trim();
	const profile = String(owner?.profile || "").trim();
	return connectionId && profile ? { connectionId, profile } : null;
}

function quotaQueryKey(scope) {
	return scope
		? [...QUOTA_QUERY_KEY, scope.connectionId, scope.profile]
		: [...QUOTA_QUERY_KEY, null, null];
}

function quotaSnapshotKey(scope) {
	return `${SNAPSHOT_KEY}:${encodeURIComponent(scope.connectionId)}:${encodeURIComponent(scope.profile)}`;
}

// cli.exec currently joins stdout and stderr. Find a complete JSON value while
// ignoring diagnostics, but only accept the shape needed by the caller. Each
// opener is considered independently so an unmatched delimiter in a diagnostic
// cannot swallow the real payload.
function parseJsonOutput(output, requiredKey) {
	const text = String(output ?? "").trim();
	if (!text) throw new Error("empty JSON output");

	const matchesSchema = (value) => {
		if (!requiredKey) return true;
		if (
			value === null ||
			typeof value !== "object" ||
			Array.isArray(value) ||
			!Object.prototype.hasOwnProperty.call(value, requiredKey)
		) {
			return false;
		}
		if (requiredKey === "providers") {
			return (
				value.providers !== null &&
				typeof value.providers === "object" &&
				!Array.isArray(value.providers)
			);
		}
		return (
			requiredKey !== "installed_sha" ||
			value.installed_sha == null ||
			typeof value.installed_sha === "string"
		);
	};

	let firstError;
	try {
		const value = JSON.parse(text);
		if (matchesSchema(value)) return value;
		firstError = new Error(`JSON output missing ${requiredKey || "expected"} schema`);
	} catch (error) {
		firstError = error;
	}

	// Cap on opener retries; see the loop below for why. Declared inside the
	// function because tests/test_widget_json.py evaluates it in isolation.
	// Recovery needs roughly openers+1 attempts, so this must exceed the number
	// of openers a real payload can hide behind. It also bounds the worst case,
	// so it cannot be unbounded. 1024 recovers well past any realistic
	// diagnostic (the fixtures use three, and 1000 objects ahead of a payload
	// still recovers) while keeping the pathological case bounded: 60k
	// unmatched openers parse in ~180ms, 200k in ~1.8s. Exceeding it throws --
	// never a partial answer.
	const maxAttempts = 1024;
	let cursor = 0;
	// Bound the retry. The scan below restarts from `start + 1` after a
	// rejected span, which is what lets a payload be recovered from inside a
	// gateway diagnostic -- but it is also quadratic, because every retry
	// re-walks the rest of the output. 16k unmatched openers measured 2.4s and
	// 60k measured 17.7s, all of it inside queryFn on the render path. A real
	// payload sits after a handful of openers at most (the diagnostic cases in
	// test_widget_json use three), so capping the attempts keeps the recovery
	// behaviour and bounds the work. Not linear, though: each attempt can still
	// rescan the tail, so the cost is attempts x remaining length. Measured on
	// this machine it stays flat to 60k (6/26/49/75/174ms at 2k-60k) and then
	// jumps to ~557ms at 120k -- bounded, not asymptotic.
	let attempts = 0;
	while (cursor < text.length) {
		if (attempts >= maxAttempts) {
			// Out of attempts. The whole-output JSON.parse at the top of this
			// function already ran and failed, which is what firstError holds;
			// re-throwing it rather than returning a partial answer is the
			// honest outcome. Recovery needs about openers+1 attempts, so the
			// 1024-attempt bound is generous -- but it is a cliff, and reaching it
			// before a valid payload means recovery fails rather than returning a
			// partial answer.
			throw firstError || new Error("invalid JSON output");
		}
		attempts += 1;
		let start = cursor;
		while (
			start < text.length &&
			text[start] !== "{" &&
			text[start] !== "["
		) {
			start += 1;
		}
		if (start >= text.length) break;

		const stack = [];
		let inString = false;
		let escaped = false;
		let end = -1;
		for (let i = start; i < text.length; i += 1) {
			const ch = text[i];
			if (inString) {
				if (escaped) escaped = false;
				else if (ch === "\\") escaped = true;
				else if (ch === '"') inString = false;
				continue;
			}
			if (ch === '"') {
				inString = true;
				continue;
			}
			if (ch === "{" || ch === "[") {
				stack.push(ch);
				continue;
			}
			if (ch !== "}" && ch !== "]") continue;

			const expected = ch === "}" ? "{" : "[";
			if (stack.length === 0 || stack[stack.length - 1] !== expected) {
				break;
			}
			stack.pop();
			if (stack.length === 0) {
				end = i;
				break;
			}
		}

		if (end < 0) {
			cursor = start + 1;
			continue;
		}
		try {
			const value = JSON.parse(text.slice(start, end + 1));
			if (matchesSchema(value)) return value;
			// A valid but unrelated JSON value is a complete diagnostic; do not
			// mistake an object nested inside it for the command response.
			cursor = end + 1;
		} catch {
			// An invalid balanced span may contain the real payload; retry from
			// its next opener instead of skipping over it.
			cursor = start + 1;
		}
	}

	throw firstError || new Error("invalid JSON output");
}

function readSnapshot(scope) {
	if (!scope) return undefined;
	try {
		const raw = CTX.storage.get(quotaSnapshotKey(scope));
		const parsed = raw ? JSON.parse(raw) : null;
		return parsed && typeof parsed === "object" ? parsed : undefined;
	} catch {
		return undefined;
	}
}

function writeSnapshot(scope, data) {
	try {
		CTX.storage.set(quotaSnapshotKey(scope), JSON.stringify(data));
	} catch {
		/* storage unavailable — the poll still works, just no instant paint */
	}
}

/** One CLI call that can never hang the UI: a gateway switch leaves the
 *  previous request sitting on a dead socket, and without a deadline the pane
 *  waits it out instead of failing over to the new gateway. */
async function quotaCli(scope, argv, timeoutMs = CLI_TIMEOUT_MS, options) {
	let timer = null;
	let expired = false;
	const deadline = Date.now() + timeoutMs;
	try {
		const result = await Promise.race([
			(async () => {
				if (!scope) throw new Error("focused quota profile unavailable");
				const routes = await host.profileRoutes();
				const matches = routes.filter(
					(route) =>
						route.connectionId === scope.connectionId &&
						route.profile === scope.profile,
				);
				if (matches.length !== 1) {
					throw new Error(
						`quota profile route ${matches.length ? "ambiguous" : "unavailable"}`,
					);
				}
				const remainingMs = deadline - Date.now();
				if (expired || remainingMs <= 0) {
					throw new Error("quota cli timeout");
				}
				const params = {
					argv: ["--profile", matches[0].targetProfile, ...argv],
				};
				return options
					? host.requestProfile(
							matches[0],
							"cli.exec",
							params,
							remainingMs,
							options,
						)
					: host.requestProfile(matches[0], "cli.exec", params, remainingMs);
			})(),
			new Promise((_resolve, reject) => {
				timer = setTimeout(
					() => {
						expired = true;
						reject(new Error("quota cli timeout"));
					},
					timeoutMs,
				);
			}),
		]);
		if (result?.blocked || result?.code !== 0) {
			throw new Error(result?.hint || result?.output || "quota cli failed");
		}
		return result;
	} finally {
		if (timer) clearTimeout(timer);
	}
}

/** Out-of-band refresh: at most one in flight, never awaited by the UI. */
async function refreshQuotaCache(scope) {
	if (!scope) return false;
	const key = JSON.stringify([scope.connectionId, scope.profile]);
	if (_refreshInFlight.has(key)) return false;
	_refreshInFlight.add(key);
	try {
		await quotaCli(scope, ["quota", "refresh"]);
		return true;
	} catch {
		return false;
	} finally {
		_refreshInFlight.delete(key);
	}
}
function useQuota() {
	const qc = useQueryClient();
	const intervalSec = useValue(refreshIntervalAtom);
	const owner = useValue(host.state.focusedSessionOwner);
	const scope = normalizeQuotaScope(owner);
	const queryKey = quotaQueryKey(scope);
	const intervalMs = Math.max(5, intervalSec) * 1000;
	return useQuery({
		queryKey,
		queryFn: async () => {
			const result = await quotaCli(scope, [
				"quota",
				"status",
				"--json",
				"--cached",
			]);
			// cli.exec exposes stdout and stderr as one string; parse the quota
			// value while ignoring gateway diagnostics. Keep the full envelope so
			// its installed_sha still feeds the update check.
			let data = null;
			try {
				data = parseJsonOutput(result.output || "{}", "providers");
			} catch {
				// Unreadable this poll. The last good snapshot is left in place --
				// writing {} here meant one bad read erased the payload, so a
				// reload afterwards painted nothing. The refresh below still
				// fires, so a transient gateway diagnostic self-heals.
			}
			if (data) writeSnapshot(scope, data);
			// Missing age (no cache yet on this gateway) counts as stale.
			const rawAge = data ? data.age_s : null;
			// `>=`, not `>`: a payload exactly one interval old is already due.
			// With `>` the poll drifted a full interval behind, permanently.
			const stale =
				rawAge == null ||
				!Number.isFinite(Number(rawAge)) ||
				Number(rawAge) >= intervalSec;
			// Fire the refresh off the poll path and update when it lands.
			if (stale) {
				void refreshQuotaCache(scope).then((refreshed) => {
					if (refreshed) qc.invalidateQueries({ queryKey });
				});
			}
			return data;
		},
		placeholderData: readSnapshot(scope),
		enabled: Boolean(scope),
		refetchInterval: intervalMs,
		// The user asked for this cadence; honour it while the window is
		// unfocused instead of silently pausing the poll.
		refetchIntervalInBackground: true,
		staleTime: Math.max(5_000, Math.floor(intervalMs / 2)),
		retry: 1,
	});
}

// Statusbar tips must use the SDK portal, not native title (unreliable in
// Electron). Preserve account/window lines; escape the short statusbar pane.
function QuotaTip({ label, children }) {
	return jsx(Tip, {
		side: "top",
		align: "start",
		boundary: "viewport",
		style: { maxWidth: "min(38rem, calc(100vw - 1.5rem))" },
		label: jsx("div", {
			style: {
				whiteSpace: "pre-wrap",
				maxHeight: "min(70vh, var(--radix-tooltip-content-available-height, 70vh))",
				overflowY: "auto",
			},
			children: label,
		}),
		children,
	});
}

// ---- single worst chip (worst mode) ---------------------------------------

function QuotaChipWithBar() {
	const { data, isError, isPlaceholderData } = useQuota();
	const stale = useCodexStale(data, isError || isPlaceholderData);
	const providers =
		data && data.providers ? statusEntries(data.providers, stale) : [];
	let worst = null;
	let worstLabel = "";
	let worstProvider = null;
	for (const [pid, p] of providers) {
		if (!isProviderEnabled(pid)) continue;
		const r = p?.unavailable_reason ? null : p?.display_accounts ? p.display_remaining : worstWindow(p);
		if (r == null) continue;
		if (worst == null || r < worst) {
			worst = r;
			worstLabel = providerDisplayName(pid, p);
			worstProvider = p;
		}
	}
	if (worst == null) {
		// Unknown Codex cannot be ranked. Keep it alongside the existing
		// balance-only fallback; money has no meaningful worst percentage.
		const fallback = providers.filter(([pid, p]) => isProviderEnabled(pid) && (p?.display_accounts || accountFacts(p).balances.length));
		if (fallback.length === 1 && fallback[0][1]?.display_accounts) return jsx(ProviderChip, { pid: fallback[0][0], provider: fallback[0][1] });
		return fallback.length
			? jsx("span", { className: "inline-flex h-full items-center", children: fallback.map(([pid, p]) => jsx(ProviderChip, { pid, provider: p, key: pid })) })
			: jsx("span", { children: "Q:none" });
	}
	const tone = toneForRemaining(worst);
	const fill = toneColor(tone);
	const tip = makeWorstTip(worstLabel, worst, data && data.providers, stale);
	const button = jsxs("button", {
		type: "button",
		"aria-label": worstLabel + " " + (worstProvider?.display_accounts ? codexValue(worst) : worst + "%") + " · Open Quota pane",
		className:
			"inline-flex items-center gap-1.5 px-1.5 py-0.5 rounded cursor-pointer hover:bg-(--chrome-action-hover) transition-colors",
		onClick: () => {
			if (typeof host.navigate === "function") host.navigate("/quota");
		},
		children: [
			jsx("span", {
				className: "text-[0.6875rem] text-(--ui-text-secondary)",
				children: worstLabel + " " + (worstProvider?.display_accounts ? codexValue(worst) : worst + "%"),
			}),
			jsx("span", {
				className:
					"inline-block h-1.5 w-10 overflow-hidden rounded-full bg-(--ui-stroke-secondary)",
				children: jsx("span", {
					className: "block h-full rounded-full",
					style: { width: worst + "%", background: fill },
				}),
			}),
		],
	});
	return jsx(QuotaTip, { label: tip, children: button });
}

// Only explicit saved labels are display text; never infer an identity.
// Re-sanitize cached input, matching the backend's 64-code-point bound.
function codexDisplayLabel(value) {
	return typeof value === "string" ? Array.from(value.replace(/[\p{Cc}\p{Cf}\p{Cs}\p{Zl}\p{Zp}]/gu, "").trim()).slice(0, 64).join("").trimEnd() : "";
}

// Keep the real provider ID for icons, settings, and routing.
function providerEntries(providers) {
	return Object.entries(providers || {}).flatMap(([pid, p]) => {
		const accounts = pid === "openai-codex" && p && Array.isArray(p.accounts)
			? p.accounts.filter(asProvider) : [];
		return accounts.length ? accounts.map((a, i) => [pid, { ...a, account_label: codexDisplayLabel(a.label) || `Account ${i + 1}` }]) : [[pid, pid === "openai-codex" && p ? { ...p, account_label: codexDisplayLabel(p.account_label) } : p]];
	});
}

// Backend account order is validated saved priority, already deduplicated.
// Keep expanded entries for the pane, but only one representative per provider
// in the status bar. This is display selection, never runtime routing.
function codexRemaining(account) {
	const windows = asWindowList(account?.windows).filter((w) => ["Session", "Weekly"].includes(w.label));
	if (account?.unavailable_reason || !windows.length || windows.some((w) => typeof w.used_percent !== "number" || !Number.isFinite(w.used_percent))) return null;
	return Math.max(0, Math.min(...windows.map((w) => 100 - w.used_percent)));
}

function codexValue(remaining) {
	return remaining == null ? "unknown" : remaining === 0 ? "limit reached" : remaining < 1 ? "<1%" : `${Math.round(remaining)}%`;
}

function useCodexStale(data, untrusted = false) {
	const interval = useValue(refreshIntervalAtom);
	const now = useNow(5_000);
	const received = useRef({ data, at: now });
	if (received.current.data !== data) received.current = { data, at: now };
	const age = data?.age_s;
	return untrusted || typeof age !== "number" || !Number.isFinite(age) || age < 0 || age + (now - received.current.at) / 1000 >= interval;
}

function statusEntries(providers, stale = false) {
	return Object.entries(providers || {}).map(([pid, provider]) => {
		const accounts = pid === "openai-codex" && provider && provider.unavailable_reason !== "no-credentials"
			? providerEntries({ [pid]: provider }).map(([, p]) => p).filter(asProvider) : [];
		if (!accounts.length) return [pid, provider];
		// A lone account needs no distinguishing name in the compact status bar.
		// Preserve the original OpenAI Codex headline even with a saved label.
		if (accounts.length === 1) accounts[0] = { ...accounts[0], account_label: "" };
		const selected = accounts.find((a) => codexRemaining(a) !== 0) || accounts[0];
		// Preserve cached display selection without ranking stale quota as fresh.
		return [pid, { ...selected, display_selected_index: accounts.indexOf(selected), display_accounts: accounts, display_stale: stale, display_cached_remaining: codexRemaining(selected), display_remaining: stale ? null : codexRemaining(selected) }];
	});
}

function codexAccountsTip(provider) {
	const lines = [];
	for (const [index, account] of provider.display_accounts.entries()) {
		const remaining = codexRemaining(account);
		const marker = index === provider.display_selected_index ? "●" : "○";
		const error = account.unavailable_reason ? ` · ${account.unavailable_reason}` : "";
		const value = codexValue(remaining) + (remaining > 0 ? " left" : "");
		const planText = account.plan ? ` · ${account.plan}` : "";
		lines.push(`${marker} ${account.account_label || `Account ${index + 1}`}${planText} · ${value}${provider.display_stale ? " · stale" : ""}${error}`);
		// Keep historical/model-specific details in the pane, not in this summary.
		if (provider.display_stale || account.unavailable_reason) continue;
		const windows = asWindowList(account.windows).filter((w) => ["Session", "Weekly"].includes(w.label));
		for (const w of windows) {
			const r = codexRemaining({ windows: [w] });
			const value = codexValue(r) + (r > 0 ? " left" : "");
			const countdown = relativeCountdown(w.reset_at);
			const reset = countdown === "resetting…" ? countdown : countdown ? `resets in ${countdown}` : "";
			// A single window already has its remaining value in the account line.
			lines.push(`  ${w.label}${windows.length > 1 ? ` · ${value}` : ""}${reset ? ` · ${reset}` : ""}`);
		}
	}
	return lines.join("\n");
}

function ProviderChip({ pid, provider }) {
	const cachedRemaining = provider?.display_stale ? provider.display_cached_remaining : provider?.display_remaining;
	const r = provider && provider.unavailable_reason ? null : provider?.display_accounts ? cachedRemaining : worstWindow(provider);
	const staleValue = Boolean(provider?.display_accounts && provider.display_stale && r != null);
	const facts = accountFacts(provider);
	const value = provider?.display_accounts ? codexValue(r) : provider && provider.unavailable_reason ? "unavailable" : r != null ? `${r}%` : facts.balances.length ? facts.balances.map(balanceText).join(" · ") : facts.available === true ? "available" : facts.available === false ? "unavailable" : "—";
	const tone = provider?.display_accounts ? (provider.display_stale ? "muted" : toneForRemaining(r)) : providerTone(provider);
	const dot = toneColor(tone);
	const label = providerDisplayName(pid, provider);
	const tip = makeProviderTip(pid, provider);
	const button = jsxs(
		"button",
		{
			type: "button",
			"aria-label": `${label} ${value}${staleValue ? " · stale" : ""} · Open Quota pane`,
			className: cn(
				"inline-flex h-full items-center gap-1 px-1.5 text-[0.6875rem]",
				"text-(--ui-text-tertiary) hover:bg-(--chrome-action-hover) hover:text-foreground transition-colors",
			),
			onClick: () => {
				if (typeof host.navigate === "function") host.navigate("/quota");
			},
			children: [
				jsx("span", { className: "inline-block h-1.5 w-1.5 rounded-full", style: { background: dot } }),
				jsx("span", { children: label }),
				jsx("span", { className: "tabular-nums", style: staleValue ? { textDecoration: "line-through" } : undefined, children: value }),
			],
		},
	);
	return jsx(QuotaTip, { label: tip, children: button });
}

// Keep other providers' window details; Codex uses its compact account summary.
function makeWorstTip(worstLabel, worst, providersObj, stale = false) {
	if (!providersObj) return `Quota · lowest ${worst}% (${worstLabel})`;
	const blocks = [];
	let hasCodex = false;
	for (const [pid, p] of statusEntries(providersObj, stale)) {
		if (!isProviderEnabled(pid) || (!p?.display_accounts && !isConfigured(p))) continue;
		if (p?.display_accounts) hasCodex = true;
		const lines = p?.display_accounts ? [makeProviderTip(pid, p)] : providerWindowLines(pid, p);
		if (lines.length) blocks.push(lines.join("\n"));
	}
	if (blocks.length === 0) return `Quota · lowest ${worst}% (${worstLabel})`;
	if (hasCodex && blocks.length === 1) return blocks[0];

	return `Quota breakdown:\n${blocks.join("\n")}${hasCodex ? "" : "\nClick to open Quota pane"}`;
}

// Build a rich multiline tip for a single provider: lists ALL its windows
// plus plan and detail lines (credits, banked resets).
function makeProviderTip(pid, provider) {
	if (provider?.display_accounts) return codexAccountsTip(provider);
	const name = providerDisplayName(pid, provider);
	if (!provider) return `${name}: unavailable`;
	const details = asList(provider && provider.details);
	if (provider.unavailable_reason) {
		// Preserve actionable diagnostics alongside the reason code.
		const lines = [`${name}: unavailable (${provider.unavailable_reason})`, ...details];
		lines.push("Click to open Quota pane");
		return lines.join("\n");
	}
	const lines = providerWindowLines(pid, provider);
	const facts = accountFacts(provider);
	lines.push(...facts.balances.map((b) => `Account balance: ${balanceText(b)}`));
	if (facts.available != null) lines.push(`API calls available: ${facts.available ? "yes" : "no"}`);
	if (provider.plan) lines.unshift(`Plan: ${provider.plan}`);
	lines.unshift(name);
	if (details.length) lines.push(...details);
	lines.push("Click to open Quota pane");
	return lines.join("\n");
}

// Shared: turn a provider's windows into tooltip lines like
// "  Session · 21% left · resets 5d 19h" / "  5.3 Codex Spark · 5h · 8% left · resets 3h 52m"
function providerWindowLines(pid, provider) {
	const windows = asWindowList(provider && provider.windows);
	const out = [];
	for (const w of windows) {
		const r = remainingPct(w);
		const reset = w.reset_at ? formatReset(w.reset_at, "relative") : "";
		out.push(
			`  ${w.label || "window"} · ${r == null ? "—" : `${r}% left`}${reset ? ` · resets ${reset}` : ""}`,
		);
	}
	return out;
}

function StatusBar() {
	const showStatusBar = useValue(showStatusBarAtom);
	const mode = useValue(statusbarModeAtom);
	const { data, isError, isPlaceholderData } = useQuota();
	const stale = useCodexStale(data, isError || isPlaceholderData);
	if (!showStatusBar) return null;
	if (mode === "worst") return jsx(QuotaChipWithBar, {});
	if (!data || !data.providers)
		return jsx(StatusDot, { tone: "muted" });
	// Keep unavailable saved accounts visible alongside healthy siblings.
	// Unconfigured providers remain hidden; visibility settings apply to all accounts.
	const entries = statusEntries(data.providers, stale)
		.filter(([pid]) => (!isError || pid === "openai-codex") && isProviderEnabled(pid))
		.filter(([, p]) => p?.display_accounts || isConfigured(p));
	if (entries.length === 0) return jsx(StatusDot, { tone: "muted" });
	return jsx("span", {
		className: "inline-flex h-full items-center",
		children: entries.map(([pid, p]) =>
			jsx(ProviderChip, { pid, provider: p, key: pid }),
		),
	});
}

// ---- pane -----------------------------------------------------------------

function QuotaBar({ value, tone }) {
	const pct = Math.max(0, Math.min(100, value == null ? 0 : value));
	return jsx("div", {
		className:
			"h-2 w-full overflow-hidden rounded-full bg-(--ui-stroke-secondary)",
		children: jsx("div", {
			className: "h-full rounded-full transition-all",
			style: { width: `${pct}%`, background: toneColor(tone) },
		}),
	});
}

// One provider card: bordered box with label + plan, a thick tonal bar per
// window, colored "% left", reset line, and provider detail lines (credits,
// banked resets). Unavailable providers render as a muted card.
function ProviderRow({ id, provider, monitor }) {
	const t = usePluginI18n(ID);
	const resetFormat = useValue(resetFormatAtom);
	// 'dense' = every window, reset time and detail line; 'clean' = just the
	// percentage bars, except OpenRouter's essential key/wallet scope details.
	const paneDetail = useValue(paneDetailAtom);
	const dense = paneDetail !== "clean";
	const reason = provider ? provider.unavailable_reason : "no-data";
	const details = asList(provider && provider.details);
	const facts = accountFacts(provider);
	const displayName = providerDisplayName(id, provider);
	// Inline sizing is intentional: plugin-only utility classes might not be
	// in the host's compiled Tailwind stylesheet.
	const cardStyle = { flexShrink: 0, minWidth: 0, overflowWrap: "anywhere" };

	if (reason) {
		// The failure lines stay visible here: for a provider whose keys failed
		// individually, `unavailable (no-data)` alone hides the very errors that
		// explain it. Clean mode stays compact, dense shows every line.
		const shown = dense ? details : details.slice(0, 6);
		const hidden = details.length - shown.length;
		return jsxs("div", {
			className:
				"flex flex-col gap-0.5 rounded-lg border border-(--ui-stroke-secondary) px-3 py-2.5 opacity-60",
			style: cardStyle,
			children: [
				jsxs("div", {
					className: "flex items-center gap-2 text-sm",
					children: [
						jsx(ProviderBadge, { pid: id }),
						jsx("span", {
							className: "font-medium text-(--ui-text-primary)",
							children: displayName,
						}),
					],
				}),
				jsx("div", {
					className: "pl-7 text-xs text-(--ui-text-tertiary)",
					children: t("unavailable", reason),
				}),
				shown.length
					? jsx("div", {
							className:
								"flex flex-col gap-0.5 pl-7 text-[0.6875rem] text-(--ui-text-tertiary)",
							children: [
								...shown.map((d, i) =>
									jsx("div", { children: d }, `${id}-u-${i}`),
								),
								hidden > 0
									? jsx("div", { children: t("moreDetails", hidden) }, `${id}-u-more`)
									: null,
							],
						})
					: null,
			],
		});
	}

	const windows = asWindowList(provider && provider.windows);
	if (windows.length === 0 && details.length === 0 && facts.balances.length === 0 && facts.available == null) {
		return jsxs("div", {
			className:
				"flex items-center gap-2 rounded-lg border border-(--ui-stroke-secondary) px-3 py-2.5 text-sm opacity-60",
			style: cardStyle,
			children: [
				jsx(ProviderBadge, { pid: id }),
				jsx("span", {
					className: "font-medium text-(--ui-text-primary)",
					children: displayName,
				}),
				jsx("span", {
					className: "text-xs text-(--ui-text-tertiary)",
					children: t("noData"),
				}),
			],
		});
	}

	return jsxs("div", {
		className:
			"flex flex-col gap-2 rounded-lg border border-(--ui-stroke-secondary) bg-(--ui-bg-elevated) px-3 py-2.5",
		style: cardStyle,
		children: [
			jsxs("div", {
				className: "flex items-center justify-between gap-2",
				children: [
					jsxs("span", {
						className:
							"flex items-center gap-2 text-sm font-semibold text-(--ui-text-primary)",
						children: [
							jsx(ProviderBadge, { pid: id }),
							displayName,
							jsx(StatusDot, {
								tone: providerTone(provider),
							}),
						],
					}),
					provider.plan
						? jsx("span", {
								className:
									"rounded bg-(--ui-control-hover-background) px-1.5 py-0.5 text-[0.6875rem] font-medium text-(--ui-text-secondary)",
								children: provider.plan,
							})
						: null,
				],
			}),
			...facts.balances.map((b) => jsxs("div", {
				key: `balance-${b.currency}`,
				children: [
					jsx("div", { className: "text-[0.6875rem] text-(--ui-text-tertiary)", children: "Account balance" }),
					jsx("div", { className: "tabular-nums font-semibold text-(--ui-text-primary)", style: { fontSize: "1.25rem", lineHeight: 1.3 }, children: balanceText(b) }),
				],
			})),
			facts.available != null ? jsx("div", {
				className: "text-xs text-(--ui-text-secondary)",
				children: `API calls available: ${facts.available ? "yes" : "no"}`,
			}) : null,
			...windows.map((w, i) => {
				const r = remainingPct(w);
				const tone = toneForRemaining(r);
				return jsxs(
					"div",
					{
						className: "flex flex-col gap-1",
						children: [
							jsxs("div", {
								className: "flex items-center justify-between gap-2 text-xs",
								children: [
									jsx("span", {
										className: "text-(--ui-text-secondary)",
										children: w.label || "window",
									}),
									jsx("span", {
										className: "tabular-nums text-[0.8125rem] font-medium",
										style: { color: toneColor(tone) },
										children: r == null ? "—" : `${r}% left`,
									}),
								],
							}),
							jsx(QuotaBar, { value: r, tone }),
							// Agent monitor extras: burn rate / "fills before reset" and
							// the used-% history. Absent without a monitor payload.
							monitor
								? jsx(ForecastLine, {
										forecast: forecastFor(burnFor(monitor.burnMap, id, provider, w.label), w, monitor.nowSec),
									})
								: null,
							monitor && monitor.history
								? jsx(Sparkline, {
										points: historyFor(monitor.history, id, provider, w.label),
										max: 100,
										height: 18,
										color: toneColor(tone === "muted" ? "good" : tone),
										label: `${w.label || "window"} history`,
									})
								: null,
							dense && w.reset_at
								? jsx("div", {
										className: "text-[0.6875rem] text-(--ui-text-quaternary)",
										children: t("reset", formatReset(w.reset_at, resetFormat)),
									})
								: null,
						],
					},
					`${id}-w-${i}`,
				);
			}),
			...details.filter((d) => (dense || id === "openrouter" || (baseProviderId(id) === "anthropic" && /^Observed /.test(d))) && (facts.available == null || !/^API calls available: (yes|no)$/.test(d))).map((d, i) =>
						jsx(
							"div",
							{
								className: "text-[0.6875rem] text-(--ui-text-tertiary)",
								children: d,
							},
							`${id}-d-${i}`,
						),
				),
		],
	});
}

